runtimeConditionals.source:
digitalAssets && digitalAssets.hasDigitalItems && digitalAssets.assets && digitalAssets.assets.length > 0 && (
                            <div className="space-y-4">
                                {/* Download Buttons Section */}
                                <DigitalDownloads assets={digitalAssets.assets} />

                                {/* License Keys Section */}
                                <div className="bg-bg-surface rounded-card p-4 md:p-6 shadow-card border border-border">
                                    <h3 className="font-bold text-text-base mb-4">License Keys</h3>
                                    {digitalAssets.assets.map((asset, idx) => (
                                        <LicenseKeyDisplay
                                            key={asset.licenseKey || idx}
                                            licenseKey={asset.licenseKey}
                                            productName={asset.productName}
                                        />
                                    ))}
                                </div>
                            </div>
                        )
